<!DOCTYPE html><html lang="vi"><head><meta charset="UTF-8"><title>Thêm tài khoản</title><link rel="stylesheet" href="/css/professional-form.css"><style>body{margin:0;background:#E9EAE8;font-family:'Times New Roman',Times,serif}.form{max-width:720px;margin:30px auto;background:#fff;border:1px solid #d6d8d6;border-top:5px solid #b91c1c;border-radius:12px;padding:24px}.form h1{color:#a31515}.field{margin-bottom:14px}.field label{display:block;font-weight:700;margin-bottom:6px}.field input,.field select{width:100%;padding:11px;border:1px solid #bdc1bd;border-radius:7px}.submit{background:#a31515;color:#fff;border:0;border-radius:7px;padding:11px 16px;font-weight:700}.back{float:right;color:#a31515;text-decoration:none;font-weight:700}</style></head><body><form class="form" method="POST"><a class="back" href="/quan_tri/tai_khoan">← Danh sách</a><h1>Thêm tài khoản mới</h1><?php if($thongBao): ?><p style="color:#b91c1c;font-weight:700"><?php echo e($thongBao); ?></p><?php endif; ?><input type="hidden" name="ma_csrf" value="<?php echo e(taoMaCsrf()); ?>"><div class="field"><label>Họ tên</label><input name="ho_ten" required></div><div class="field"><label>Số định danh (12 số)</label><input name="so_dinh_danh" required maxlength="12"></div><div class="field"><label>Email</label><input type="email" name="email"></div><div class="field"><label>Vai trò</label><select name="ma_vai_tro"><option value="1">Công dân</option><option value="2">Cán bộ</option><option value="3">Quản trị viên</option></select></div><button class="submit">Tạo tài khoản</button></form></body></html>
